class $$ArcsTableTableManager extends RootTableManager<
    _$AppDatabase,
    $ArcsTable,
    Arc,
    $$ArcsTableFilterComposer,
    $$ArcsTableOrderingComposer,
    $$ArcsTableAnnotationComposer,
    $$ArcsTableCreateCompanionBuilder,
    $$ArcsTableUpdateCompanionBuilder,
    (Arc, $$ArcsTableReferences),
    Arc,
    PrefetchHooks Function(
        {bool novelId, bool volumeId, bool chaptersRefs, bool scenesRefs})> {
  $$ArcsTableTableManager(_$AppDatabase db, $ArcsTable table)
      : super(TableManagerState(
          db: db,
          table: table,
          createFilteringComposer: () =>
              $$ArcsTableFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $$ArcsTableOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $$ArcsTableAnnotationComposer($db: db, $table: table),
          updateCompanionCallback: ({
            Value<String> id = const Value.absent(),
            Value<String> novelId = const Value.absent(),
            Value<String> volumeId = const Value.absent(),
            Value<String> title = const Value.absent(),
            Value<String?> description = const Value.absent(),
            Value<int> position = const Value.absent(),
            Value<bool> collapsed = const Value.absent(),
            Value<int> createdAt = const Value.absent(),
            Value<int> updatedAt = const Value.absent(),
            Value<int?> archivedAt = const Value.absent(),
            Value<int?> deletedAt = const Value.absent(),
            Value<int> rowid = const Value.absent(),
          }) =>
              ArcsCompanion(
            id: id,
            novelId: novelId,
            volumeId: volumeId,
            title: title,
            description: description,
            position: position,
            collapsed: collapsed,
            createdAt: createdAt,
            updatedAt: updatedAt,
            archivedAt: archivedAt,
            deletedAt: deletedAt,
            rowid: rowid,
          ),
          createCompanionCallback: ({
            required String id,
            required String novelId,
            required String volumeId,
            required String title,
            Value<String?> description = const Value.absent(),
            required int position,
            Value<bool> collapsed = const Value.absent(),
            required int createdAt,
            required int updatedAt,
            Value<int?> archivedAt = const Value.absent(),
            Value<int?> deletedAt = const Value.absent(),
            Value<int> rowid = const Value.absent(),
          }) =>
              ArcsCompanion.insert(
            id: id,
            novelId: novelId,
            volumeId: volumeId,
            title: title,
            description: description,
            position: position,
            collapsed: collapsed,
            createdAt: createdAt,
            updatedAt: updatedAt,
            archivedAt: archivedAt,
            deletedAt: deletedAt,
            rowid: rowid,
          ),
          withReferenceMapper: (p0) => p0
              .map((e) =>
                  (e.readTable(table), $$ArcsTableReferences(db, table, e)))
              .toList(),
          prefetchHooksCallback: (
              {novelId = false,
              volumeId = false,
              chaptersRefs = false,
              scenesRefs = false}) {
            return PrefetchHooks(
              db: db,
              explicitlyWatchedTables: [
                if (chaptersRefs) db.chapters,
                if (scenesRefs) db.scenes
              ],
              addJoins: <
                  T extends TableManagerState<
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic>>(state) {
                if (novelId) {
                  state = state.withJoin(
                    currentTable: table,
                    currentColumn: table.novelId,
                    referencedTable: $$ArcsTableReferences._novelIdTable(db),
                    referencedColumn:
                        $$ArcsTableReferences._novelIdTable(db).id,
                  ) as T;
                }
                if (volumeId) {
                  state = state.withJoin(
                    currentTable: table,
                    currentColumn: table.volumeId,
                    referencedTable: $$ArcsTableReferences._volumeIdTable(db),
                    referencedColumn:
                        $$ArcsTableReferences._volumeIdTable(db).id,
                  ) as T;
                }

                return state;
              },
              getPrefetchedDataCallback: (items) async {
                return [
                  if (chaptersRefs)
                    await $_getPrefetchedData<Arc, $ArcsTable, Chapter>(
                        currentTable: table,
                        referencedTable:
                            $$ArcsTableReferences._chaptersRefsTable(db),
                        managerFromTypedResult: (p0) =>
                            $$ArcsTableReferences(db, table, p0).chaptersRefs,
                        referencedItemsForCurrentItem: (item,
                                referencedItems) =>
                            referencedItems.where((e) => e.arcId == item.id),
                        typedResults: items),
                  if (scenesRefs)
                    await $_getPrefetchedData<Arc, $ArcsTable, Scene>(
                        currentTable: table,
                        referencedTable:
                            $$ArcsTableReferences._scenesRefsTable(db),
                        managerFromTypedResult: (p0) =>
                            $$ArcsTableReferences(db, table, p0).scenesRefs,
                        referencedItemsForCurrentItem: (item,
                                referencedItems) =>
                            referencedItems.where((e) => e.arcId == item.id),
                        typedResults: items)
                ];
              },
            );
          },
        ));
}

